import { _decorator, Component, Node, Vec3, Quat, input, Input, EventMouse, EventKeyboard, KeyCode } from 'cc';
const { ccclass, property } = _decorator;

@ccclass('CameraFollow')
export class CameraFollow extends Component {
    @property target: Node | null = null;
    @property distance = 10;
    @property height = 6;
    @property yaw = 0;        // degrees
    @property pitch = 25;     // degrees
    @property mouseSensitivity = 0.3;
    @property smoothness = 8;

    private dragging = false;
    private lastX = 0;
    private lastY = 0;

    onLoad() {
        input.on(Input.EventType.MOUSE_DOWN, this.onMouseDown, this);
        input.on(Input.EventType.MOUSE_UP, this.onMouseUp, this);
        input.on(Input.EventType.MOUSE_MOVE, this.onMouseMove, this);
        input.on(Input.EventType.MOUSE_WHEEL, this.onWheel, this);
        input.on(Input.EventType.KEY_DOWN, this.onKey, this);
    }

    onDestroy() {
        input.off(Input.EventType.MOUSE_DOWN, this.onMouseDown, this);
        input.off(Input.EventType.MOUSE_UP, this.onMouseUp, this);
        input.off(Input.EventType.MOUSE_MOVE, this.onMouseMove, this);
        input.off(Input.EventType.MOUSE_WHEEL, this.onWheel, this);
        input.off(Input.EventType.KEY_DOWN, this.onKey, this);
    }

    private onMouseDown(e: EventMouse) {
        this.dragging = true;
        this.lastX = e.getLocationX();
        this.lastY = e.getLocationY();
    }
    private onMouseUp() { this.dragging = false; }

    private onMouseMove(e: EventMouse) {
        const x = e.getLocationX(), y = e.getLocationY();
        if (this.dragging) {
            const dx = x - this.lastX, dy = y - this.lastY;
            this.yaw -= dx * this.mouseSensitivity;
            this.pitch = Math.max(5, Math.min(70, this.pitch - dy * this.mouseSensitivity));
        }
        this.lastX = x; this.lastY = y;
    }

    private onWheel(e: EventMouse) {
        const sy = (e as any).getScrollY ? (e as any).getScrollY() : 0;
        this.distance = Math.max(4, Math.min(20, this.distance - sy * 0.01));
    }

    private onKey(e: EventKeyboard) {
        if (e.keyCode === KeyCode.ARROW_LEFT)  this.yaw += 5;
        if (e.keyCode === KeyCode.ARROW_RIGHT) this.yaw -= 5;
        if (e.keyCode === KeyCode.ARROW_UP)    this.pitch = Math.min(70, this.pitch + 3);
        if (e.keyCode === KeyCode.ARROW_DOWN)  this.pitch = Math.max(5, this.pitch - 3);
    }

    lateUpdate(dt: number) {
        if (!this.target) return;
        const tp = this.target.worldPosition;
        const yawRad = this.yaw * Math.PI / 180;
        const pitchRad = this.pitch * Math.PI / 180;
        const d = this.distance;
        const offsetX = -Math.sin(yawRad) * Math.cos(pitchRad) * d;
        const offsetZ = -Math.cos(yawRad) * Math.cos(pitchRad) * d;
        const offsetY = Math.sin(pitchRad) * d + this.height * 0.3;

        const desired = new Vec3(tp.x + offsetX, tp.y + offsetY, tp.z + offsetZ);
        const cur = this.node.worldPosition;
        const t = Math.min(1, dt * this.smoothness);
        const np = new Vec3(
            cur.x + (desired.x - cur.x) * t,
            cur.y + (desired.y - cur.y) * t,
            cur.z + (desired.z - cur.z) * t,
        );
        this.node.setWorldPosition(np);

        // Look at target
        const q = new Quat();
        Quat.fromEuler(q, -this.pitch, this.yaw, 0);
        this.node.setWorldRotation(q);
    }
}